# Test Suite for U04_2: Patient-Doctor-Chemist-Lab Interaction

```

// Test Case 1: Patient generates a consultation request
public class ConsultationRequestTest {
    @Test
    public void whenPatientGeneratesConsultationRequest_thenDoctorSeesRequestAndGivesDiagnosis() {
        // Arrange
        Patient patient = new Patient();
        Doctor doctor = mock(Doctor.class);
        ConsultationRequest request = patient.generateConsultationRequest();

        // Act
        doctor.receiveConsultationRequest(request);

        // Assert
        assertEquals(doctor.getDiagnosis(), request.getDiagnosis());
    }
}

// Test Case 2: Doctor sends prescription to patient, chemist, and labs
public class PrescriptionTest {
    @Test
    public void whenDoctorSendsPrescription_thenPatientChemistAndLabsReceivePrescription() {
        // Arrange
        Doctor doctor = mock(Doctor.class);
        Prescription prescription = doctor.generatePrescription();
        Patient patient = new Patient();
        Chemist chemist = mock(Chemist.class);
        Lab lab = mock(Lab.class);

        // Act
        doctor.sendPrescription(prescription, patient, chemist, lab);

        // Assert
        assertTrue(chemist.receivedPrescription());
        assertTrue(lab.receivedPrescription());
    }
}

// Test Case 3: Chemist delivers medicines to patient
public class MedicinesDeliveryTest {
    @Test
    public void whenChemistDeliversMedicines_thenPatientReceivesMedicines() {
        // Arrange
        Chemist chemist = mock(Chemist.class);
        Prescription prescription = mock(Prescription.class);
        Patient patient = new Patient();

        // Act
        chemist.deliverMedicines(prescription, patient);

        // Assert
        assertTrue(patient.receivedMedicines());
    }
}

// Test Case 4: Labs collect specimen and deliver lab report
public class LabReportTest {
    @Test
    public void whenLabsCollectSpecimenAndDeliverLabReport_thenPatientReceivesLabReport() {
        // Arrange
        Lab lab = mock(Lab.class);
        Prescription prescription = mock(Prescription.class);
        Patient patient = new Patient();

        // Act
        lab.collectSpecimenAndDeliverLabReport(prescription, patient);

        // Assert
        assertTrue(patient.receivedLabReport());
    }
}

// Test Case 5: Admin sets up specialties
public class AdminSpecialtiesTest {
    @Test
    public void whenAdminSetsUpSpecialties_thenSpecialtiesAreAvailable() {
        // Arrange
        Admin admin = mock(Admin.class);
        Specialty specialty = new Specialty();

        // Act
        admin.setupSpecialties(specialty);

        // Assert
        assertTrue(specialty.isAvailable());
    }
}

// Test Case 6: Admin adds doctors
public class AdminAddDoctorsTest {
    @Test
    public void whenAdminAddsDoctors_thenDoctorsAreAvailable() {
        // Arrange
        Admin admin = mock(Admin.class);
        Doctor doctor = new Doctor();

        // Act
        admin.addDoctor(doctor);

        // Assert
        assertTrue(admin.getDoctors().contains(doctor));
    }
}

// Test Case 7: Admin adds labs and pharmacy
public class AdminAddLabsPharmacyTest {
    @Test
    public void whenAdminAddsLabsAndPharmacy_thenLabsAndPharmacyAreAvailable() {
        // Arrange
        Admin admin = mock(Admin.class);
        Lab lab = new Lab();
        Pharmacy pharmacy = new Pharmacy();

        // Act
        admin.addLab(lab);
        admin.addPharmacy(pharmacy);

        // Assert
        assertTrue(admin.getLabs().contains(lab));
        assertTrue(admin.getPharmacies().contains(pharmacy));
    }
}

// Test Case 8: Admin edits doctor information
public class AdminEditDoctorInfoTest {
    @Test
    public void whenAdminEditsDoctorInfo_thenDoctorInformationIsUpdated() {
        // Arrange
        Admin admin = mock(Admin.class);
        Doctor doctor = new Doctor();
        String newInfo = "Updated Info";

        // Act
        admin.editDoctorInfo(doctor, newInfo);

        // Assert
        assertEquals(doctor.getInfo(), newInfo);
    }
}
